// Portfolio Modal
const modal = document.getElementById('portfolio-modal');
const modalClose = document.querySelector('.modal-close');
const modalTitle = document.querySelector('.modal-title');
const modalCategory = document.querySelector('.modal-category');
const modalCounter = document.querySelector('.modal-counter');
const modalGalleryTabs = document.querySelector('.modal-gallery-tabs');
const modalPrevBtn = document.querySelector('.gallery-arrow.prev');
const modalNextBtn = document.querySelector('.gallery-arrow.next');
const modalImg = document.querySelector('.modal-img');
const modalVideo = document.querySelector('.modal-video');
const modalIframe = document.querySelector('.modal-iframe');
const modalMediaWrapper = document.querySelector('.modal-media-wrapper');
const portfolioItems = document.querySelectorAll('.portfolio-item, .portfolio-item-new');

let currentGallery = null;
let currentGalleryIndex = 0;

// In-memory cache for Work 01 (Blender 3D images) & Work 02 (After Effects MP4 Blob URLs)
const videoBlobCache = {};
const videoFetchPromises = {};
const BLENDER_FAST_CACHE = {"Illustrator_3D.png":"data:image/jpeg;base64,","Logo_3D.png":"data:image/jpeg;base64,","Photoshop_3D.png":"data:image/jpeg;base64,"}
;

const VIDEO_POSTER_CACHE = {"Apple.mp4":"data:image/jpeg;base64,","Coca cola.mp4":"data:image/jpeg;base64,","Coca Cola.mp4":"data:image/jpeg;base64,","Композиция.mp4":"data:image/jpeg;base64,"};

// Pre-decode BLENDER_FAST_CACHE images into memory so mobile browsers render them in 0ms
const decodedBlenderImages = {};
Object.keys(BLENDER_FAST_CACHE).forEach(key => {
    const img = new Image();
    img.decoding = 'async';
    img.src = BLENDER_FAST_CACHE[key];
    decodedBlenderImages[key] = img;
});

// Pause any in-flight background card image downloads so Work 01 & 02 get 100% bandwidth
const pausedBgImages = [];
function pauseBackgroundImageDownloads() {
    document.querySelectorAll('.item-image img').forEach(img => {
        const currentSrc = img.getAttribute('src');
        if (currentSrc && !currentSrc.startsWith('data:') && !img.complete) {
            img.dataset.pausedSrc = currentSrc;
            img.src = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
            pausedBgImages.push(img);
        }
    });
}

function resumeBackgroundImageDownloads() {
    while (pausedBgImages.length > 0) {
        const img = pausedBgImages.pop();
        if (img && img.dataset.pausedSrc) {
            img.src = img.dataset.pausedSrc;
            delete img.dataset.pausedSrc;
        }
    }
}

// Pre-fetch a video candidate list into a local Blob URL (with explicit video/mp4 MIME for iOS Safari)
function prefetchVideoToBlob(work) {
    if (!work || !work.src || window.location.protocol === 'file:') return Promise.resolve(null);
    const key = work.src;
    if (videoBlobCache[key]) return Promise.resolve(videoBlobCache[key]);
    if (videoFetchPromises[key]) return videoFetchPromises[key];

    const candidates = [work.src].concat(work.fallbacks || (work.fallback ? [work.fallback] : [])).filter(Boolean);
    let idx = 0;

    const tryNext = () => {
        if (idx >= candidates.length) return Promise.resolve(null);
        const url = encodeURI(candidates[idx++]);
        return fetch(url)
            .then(res => {
                if (!res.ok) throw new Error('HTTP ' + res.status);
                return res.blob();
            })
            .then(blob => {
                if (!blob || blob.size < 1000) throw new Error('Empty blob');
                const mp4Blob = blob.type === 'video/mp4' ? blob : new Blob([blob], { type: 'video/mp4' });
                const blobUrl = URL.createObjectURL(mp4Blob);
                videoBlobCache[key] = blobUrl;
                return blobUrl;
            })
            .catch(() => tryNext());
    };

    videoFetchPromises[key] = tryNext();
    return videoFetchPromises[key];
}

function setModalLoading(isLoading) {
    if (modalMediaWrapper) {
        modalMediaWrapper.classList.toggle('is-loading', Boolean(isLoading));
    }
}

function resetModalVideo() {
    if (!modalVideo) return;
    modalVideo.onloadedmetadata = null;
    modalVideo.onloadeddata = null;
    modalVideo.oncanplay = null;
    modalVideo.onplaying = null;
    modalVideo.onwaiting = null;
    modalVideo.onerror = null;
    modalVideo.pause();
    modalVideo.style.display = 'none';
    modalVideo.removeAttribute('poster');
    modalVideo.removeAttribute('src');
    modalVideo.load();
}

function extractYouTubeId(input) {
    if (!input) return '';
    const trimmed = input.trim();
    if (/^[a-zA-Z0-9_-]{11}$/.test(trimmed)) return trimmed;
    const match = trimmed.match(/(?:youtube\.com\/(?:watch\?.*v=|embed\/|shorts\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/);
    return match ? match[1] : trimmed;
}

function showGalleryItem(index) {
    if (!currentGallery || !currentGallery.length) return;
    if (index < 0) index = currentGallery.length - 1;
    if (index >= currentGallery.length) index = 0;
    
    currentGalleryIndex = index;
    const work = currentGallery[index];
    
    // Free 100% network bandwidth for modal gallery item
    pauseBackgroundImageDownloads();

    // Update Title, Category & Counter
    modalTitle.textContent = work.title || '';
    modalCategory.textContent = work.tag || '';
    if (modalCounter) {
        modalCounter.textContent = `${String(index + 1).padStart(2, '0')} / ${String(currentGallery.length).padStart(2, '0')}`;
    }
    
    // Update tabs active state & auto-scroll active pill into view on mobile
    if (modalGalleryTabs) {
        const pills = modalGalleryTabs.querySelectorAll('.gallery-pill');
        pills.forEach((p, idx) => {
            if (idx === index) {
                p.classList.add('active');
                if (typeof p.scrollIntoView === 'function') {
                    p.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
                }
            } else {
                p.classList.remove('active');
            }
        });
    }
    
    const isYouTube = work.type === 'youtube' || (work.src && /(?:youtube\.com|youtu\.be)/.test(work.src));
    const useLocalFallback = isYouTube && window.location.protocol === 'file:' && work.fallback;

    // Show YouTube, video, or image
    if (isYouTube && !useLocalFallback) {
        if (modalImg) modalImg.style.display = 'none';
        resetModalVideo();
        setModalLoading(false);
        let iframeEl = modalIframe;
        if (!iframeEl && modalMediaWrapper) {
            iframeEl = document.createElement('iframe');
            iframeEl.className = 'modal-iframe';
            iframeEl.style.cssText = 'width:100%;height:100%;max-height:70vh;border-radius:8px;background:#000;border:none;';
            iframeEl.setAttribute('allow', 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share');
            iframeEl.setAttribute('allowfullscreen', '');
            modalMediaWrapper.appendChild(iframeEl);
        }
        if (iframeEl) {
            const ytId = extractYouTubeId(work.src);
            iframeEl.style.display = 'block';
            iframeEl.src = `https://www.youtube.com/embed/${ytId}?autoplay=1&mute=1&rel=0&modestbranding=1&playsinline=1&loop=1&playlist=${ytId}`;
        }
    } else if (work.type === 'video' || useLocalFallback) {
        if (modalImg) modalImg.style.display = 'none';
        const iframeEl = modalIframe || document.querySelector('.modal-iframe');
        if (iframeEl) {
            iframeEl.style.display = 'none';
            iframeEl.src = '';
        }
        if (modalVideo) {
            resetModalVideo();
            modalVideo.style.display = 'block';
            modalVideo.muted = true;
            modalVideo.defaultMuted = true;
            modalVideo.playsInline = true;
            modalVideo.setAttribute('playsinline', '');
            modalVideo.setAttribute('webkit-playsinline', '');
            modalVideo.autoplay = true;
            modalVideo.loop = true;
            modalVideo.preload = 'auto';
            const primarySrc = useLocalFallback ? work.fallback : work.src;
            const posterDataUrl = VIDEO_POSTER_CACHE[primarySrc];
            if (posterDataUrl) {
                modalVideo.poster = posterDataUrl;
            }
            const cachedBlobUrl = videoBlobCache[primarySrc];
            const candidates = [primarySrc].concat(work.fallbacks || (work.fallback ? [work.fallback] : [])).filter(Boolean);

            const tryPlay = () => {
                setModalLoading(false);
                modalVideo.muted = true;
                if (modalVideo.paused) {
                    modalVideo.play().catch(() => {});
                }
            };
            modalVideo.onloadeddata = tryPlay;
            modalVideo.oncanplay = tryPlay;
            modalVideo.onplaying = () => setModalLoading(false);

            let candidateIdx = 0;
            const loadDirectCandidate = (idx) => {
                if (idx >= candidates.length) {
                    setModalLoading(false);
                    return;
                }
                candidateIdx = idx;
                modalVideo.onerror = () => {
                    if (candidateIdx + 1 < candidates.length) {
                        loadDirectCandidate(candidateIdx + 1);
                    } else {
                        setModalLoading(false);
                    }
                };
                modalVideo.src = encodeURI(candidates[idx]);
                modalVideo.load();
                tryPlay();
            };

            if (cachedBlobUrl) {
                setModalLoading(false);
                // If a mobile in-app WebView rejects blob: URLs, fall back seamlessly to direct stream
                modalVideo.onerror = () => {
                    delete videoBlobCache[primarySrc];
                    loadDirectCandidate(0);
                };
                modalVideo.src = cachedBlobUrl;
                modalVideo.load();
                tryPlay();
            } else {
                setModalLoading(!posterDataUrl);
                loadDirectCandidate(0);
            }

            // Also warm up the other videos in this gallery in background
            currentGallery.forEach((otherWork, otherIdx) => {
                if (otherIdx !== index && otherWork.type === 'video') {
                    prefetchVideoToBlob(otherWork);
                }
            });
        }
    } else {
        resetModalVideo();
        const iframeEl = modalIframe || document.querySelector('.modal-iframe');
        if (iframeEl) {
            iframeEl.style.display = 'none';
            iframeEl.src = '';
        }
        if (modalImg) {
            modalImg.style.display = 'block';
            const fastDataUrl = BLENDER_FAST_CACHE[work.src];
            if (fastDataUrl) {
                setModalLoading(false);
                modalImg.style.background = `url("${fastDataUrl}") center/contain no-repeat`;
            } else {
                const encodedSrc = encodeURI(work.src);
                setModalLoading(true);
                modalImg.style.background = `url("${encodedSrc}") center/contain no-repeat`;
                const probe = new Image();
                probe.onload = () => setModalLoading(false);
                probe.onerror = () => {
                    if (work.fallback) {
                        const fbUrl = encodeURI(work.fallback);
                        modalImg.style.background = `url("${fbUrl}") center/contain no-repeat`;
                    }
                    setModalLoading(false);
                };
                probe.src = encodedSrc;
            }
        }
    }
}

if (modalPrevBtn) {
    modalPrevBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        showGalleryItem(currentGalleryIndex - 1);
    });
}

if (modalNextBtn) {
    modalNextBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        showGalleryItem(currentGalleryIndex + 1);
    });
}

// Touch swipe navigation (left/right) inside modal for mobile devices
if (modalMediaWrapper) {
    let touchStartX = 0;
    let touchStartY = 0;
    modalMediaWrapper.addEventListener('touchstart', (e) => {
        if (!e.touches || !e.touches.length) return;
        touchStartX = e.touches[0].clientX;
        touchStartY = e.touches[0].clientY;
    }, { passive: true });

    modalMediaWrapper.addEventListener('touchend', (e) => {
        if (!currentGallery || currentGallery.length <= 1 || !e.changedTouches || !e.changedTouches.length) return;
        const dx = e.changedTouches[0].clientX - touchStartX;
        const dy = e.changedTouches[0].clientY - touchStartY;
        if (Math.abs(dx) > 42 && Math.abs(dx) > Math.abs(dy) * 1.3) {
            if (dx < 0) {
                showGalleryItem(currentGalleryIndex + 1);
            } else {
                showGalleryItem(currentGalleryIndex - 1);
            }
        }
    }, { passive: true });
}

// Preload first gallery item on hover/touch so modal opens instantaneously
portfolioItems.forEach(item => {
    if (item.dataset.gallery) {
        const warmUpGallery = () => {
            try {
                const list = JSON.parse(item.dataset.gallery);
                if (!list || !list.length) return;
                const first = list[0];
                if (first.type === 'img' && first.src) {
                    const preloadImg = new Image();
                    preloadImg.decoding = 'async';
                    preloadImg.src = encodeURI(first.src);
                } else if (first.type === 'video' && first.src) {
                    const link = document.createElement('link');
                    link.rel = 'preload';
                    link.as = 'video';
                    link.href = encodeURI(first.src);
                    document.head.appendChild(link);
                }
            } catch (err) {}
        };
        item.addEventListener('mouseenter', warmUpGallery, { once: true, passive: true });
        item.addEventListener('touchstart', warmUpGallery, { once: true, passive: true });
    }

    item.addEventListener('click', (e) => {
        e.preventDefault();
        
        if (item.dataset.pdf) {
            if (window.innerWidth <= 768 || /Mobi|Android/i.test(navigator.userAgent)) {
                window.location.href = item.dataset.pdf;
            } else {
                window.open(item.dataset.pdf, '_blank');
            }
            return;
        }
        
        if (item.dataset.figma) {
            if (window.innerWidth <= 768 || /Mobi|Android/i.test(navigator.userAgent)) {
                window.location.href = item.dataset.figma;
            } else {
                window.open(item.dataset.figma, '_blank');
            }
            return;
        }

        // Multi-work Gallery Mode (Blender 3D Collection / After Effects Showcase)
        if (item.dataset.gallery) {
            try {
                currentGallery = JSON.parse(item.dataset.gallery);
            } catch (err) {
                currentGallery = null;
            }
        } else {
            currentGallery = null;
        }

        if (currentGallery && currentGallery.length > 0) {
            if (modalPrevBtn) modalPrevBtn.style.display = currentGallery.length > 1 ? 'flex' : 'none';
            if (modalNextBtn) modalNextBtn.style.display = currentGallery.length > 1 ? 'flex' : 'none';
            
            if (modalGalleryTabs) {
                modalGalleryTabs.innerHTML = '';
                modalGalleryTabs.style.display = currentGallery.length > 1 ? 'flex' : 'none';
                currentGallery.forEach((work, idx) => {
                    const pill = document.createElement('button');
                    pill.className = 'gallery-pill' + (idx === 0 ? ' active' : '');
                    pill.textContent = work.title;
                    pill.addEventListener('click', (ev) => {
                        ev.stopPropagation();
                        showGalleryItem(idx);
                    });
                    modalGalleryTabs.appendChild(pill);
                });
            }
            
            // Free GPU for video: pause background video
            document.querySelectorAll('.item-image video').forEach(v => v.pause());

            showGalleryItem(0);
            modal.classList.add('active');
            document.body.style.overflow = 'hidden';
            return;
        }

        // Single Item Mode
        if (modalPrevBtn) modalPrevBtn.style.display = 'none';
        if (modalNextBtn) modalNextBtn.style.display = 'none';
        if (modalGalleryTabs) modalGalleryTabs.style.display = 'none';
        if (modalCounter) modalCounter.textContent = '';

        const isNewLayout = item.classList.contains('portfolio-item-new');
        let title = '';
        let category = '';
        let imgElement = null;

        if (isNewLayout) {
            imgElement = item.querySelector('.item-image img');
            if (item.dataset.title) {
                title = item.dataset.title;
            } else {
                title = 'Project ' + item.querySelector('.item-number').textContent;
            }
            
            const tags = item.querySelectorAll('.item-tags p');
            category = Array.from(tags).map(t => t.textContent).join(', ');
            
        } else {
            const h3 = item.querySelector('h3');
            const p = item.querySelector('p');
            if (h3) title = h3.textContent;
            if (p) category = p.textContent;
            imgElement = item.querySelector('.placeholder-img');
        }
        
        modalTitle.textContent = title;
        modalCategory.textContent = category;
        
        // Free GPU for video: pause background video
        document.querySelectorAll('.item-image video').forEach(v => v.pause());

        const singleIframe = modalIframe || document.querySelector('.modal-iframe');
        if (singleIframe) {
            singleIframe.style.display = 'none';
            singleIframe.src = '';
        }

        if (item.dataset.video) {
            if (modalImg) modalImg.style.display = 'none';
            if (modalVideo) {
                resetModalVideo();
                setModalLoading(true);
                modalVideo.style.display = 'block';
                modalVideo.onloadeddata = () => setModalLoading(false);
                modalVideo.oncanplay = () => setModalLoading(false);
                modalVideo.src = encodeURI(item.dataset.video);
                modalVideo.load();
                modalVideo.play().catch(() => {});
            }
        } else {
            resetModalVideo();
            setModalLoading(false);
            if (modalImg) {
                modalImg.style.display = 'block';
                if (imgElement && imgElement.tagName.toLowerCase() === 'img' && imgElement.currentSrc) {
                    modalImg.style.background = `url("${imgElement.currentSrc}") center/contain no-repeat`;
                } else if (item.dataset.img) {
                    modalImg.style.background = `url("${encodeURI(item.dataset.img)}") center/contain no-repeat`;
                } else if (imgElement) {
                    const bgGradient = window.getComputedStyle(imgElement).background;
                    modalImg.style.background = bgGradient;
                }
            }
        }
        
        modal.classList.add('active');
        document.body.style.overflow = 'hidden';
    });
});

const closeModal = () => {
    if (document.fullscreenElement || document.webkitFullscreenElement) {
        if (document.exitFullscreen) {
            document.exitFullscreen().catch(() => {});
        } else if (document.webkitExitFullscreen) {
            document.webkitExitFullscreen();
        }
    }
    modal.classList.remove('active');
    document.body.style.overflow = '';
    currentGallery = null;
    setModalLoading(false);
    resetModalVideo();
    const iframeEl = modalIframe || document.querySelector('.modal-iframe');
    if (iframeEl) {
        iframeEl.style.display = 'none';
        iframeEl.src = '';
    }
    // Resume any paused background card image downloads
    resumeBackgroundImageDownloads();
    // Resume background card videos
    document.querySelectorAll('.item-image video').forEach(v => v.play().catch(() => {}));
};

modalClose.addEventListener('click', closeModal);

modal.addEventListener('click', (e) => {
    if (e.target === modal) {
        closeModal();
    }
});

// Toggle Fullscreen on video click (First click enters fullscreen, next click exits, with iOS webkitEnterFullscreen support)
if (modalVideo) {
    modalVideo.controls = false;
    modalVideo.addEventListener('click', (e) => {
        e.stopPropagation();
        if (modalVideo.paused) {
            modalVideo.muted = true;
            modalVideo.play().catch(() => {});
            return;
        }
        if (!document.fullscreenElement && !document.webkitFullscreenElement) {
            if (modalVideo.requestFullscreen) {
                modalVideo.requestFullscreen().catch(() => {});
            } else if (modalVideo.webkitRequestFullscreen) {
                modalVideo.webkitRequestFullscreen();
            } else if (modalVideo.webkitEnterFullscreen) {
                modalVideo.webkitEnterFullscreen();
            } else if (modalVideo.msRequestFullscreen) {
                modalVideo.msRequestFullscreen();
            }
        } else {
            if (document.exitFullscreen) {
                document.exitFullscreen().catch(() => {});
            } else if (document.webkitExitFullscreen) {
                document.webkitExitFullscreen();
            } else if (document.msExitFullscreen) {
                document.msExitFullscreen();
            }
        }
    });
}

// Toggle Fullscreen on image click
if (modalImg) {
    modalImg.addEventListener('click', (e) => {
        e.stopPropagation();
        if (!document.fullscreenElement && !document.webkitFullscreenElement) {
            if (modalImg.requestFullscreen) {
                modalImg.requestFullscreen().catch(() => {});
            } else if (modalImg.webkitRequestFullscreen) {
                modalImg.webkitRequestFullscreen();
            }
        } else {
            if (document.exitFullscreen) {
                document.exitFullscreen().catch(() => {});
            } else if (document.webkitExitFullscreen) {
                document.webkitExitFullscreen();
            }
        }
    });
}

window.addEventListener('keydown', (e) => {
    if (modal.classList.contains('active')) {
        if (e.key === 'Escape') {
            if (document.fullscreenElement || document.webkitFullscreenElement) {
                return; // Let browser exit fullscreen first
            }
            closeModal();
        } else if (e.key === 'ArrowLeft' && currentGallery) {
            showGalleryItem(currentGalleryIndex - 1);
        } else if (e.key === 'ArrowRight' && currentGallery) {
            showGalleryItem(currentGalleryIndex + 1);
        }
    }
});

// Contact Form & Direct Contacts Modal
const contactForm = document.querySelector('.contact-form');
const contactModal = document.getElementById('contact-modal');
const contactModalClose = document.getElementById('contact-modal-close');

function openContactModal(name, msg) {
    if (!contactModal) return;
    
    // If visitor filled out the form, pre-populate message for WhatsApp
    const modalWaBtn = document.getElementById('modal-wa-btn');
    if (modalWaBtn) {
        const baseWa = modalWaBtn.getAttribute('data-base-href') || 'https://wa.me/992900444066';
        if (msg || name) {
            const textParam = encodeURIComponent(`Здравствуйте, Мухаммадризо! Меня зовут ${name || 'Клиент'}. ${msg || ''}`.trim());
            modalWaBtn.href = `${baseWa}?text=${textParam}`;
        } else {
            modalWaBtn.href = baseWa;
        }
    }

    contactModal.classList.add('active');
    document.body.style.overflow = 'hidden';
}

function closeContactModal() {
    if (!contactModal) return;
    contactModal.classList.remove('active');
    document.body.style.overflow = '';
}

if (contactForm) {
    contactForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const nameInput = document.getElementById('name');
        const msgInput = document.getElementById('message');
        const name = nameInput ? nameInput.value.trim() : '';
        const msg = msgInput ? msgInput.value.trim() : '';
        openContactModal(name, msg);
    });
}

if (contactModalClose) {
    contactModalClose.addEventListener('click', closeContactModal);
}

if (contactModal) {
    contactModal.addEventListener('click', (e) => {
        if (e.target === contactModal) {
            closeContactModal();
        }
    });
}

// Close contact modal on Escape
window.addEventListener('keydown', (e) => {
    if (contactModal && contactModal.classList.contains('active')) {
        if (e.key === 'Escape') {
            closeContactModal();
        }
    }
});

// Custom cursor hover support for newly added elements
if (!isTouchDevice && cursor && follower) {
    const newHoverItems = document.querySelectorAll('.quick-contact-badge, .contact-channel-item, #contact-modal-close, .footer-link');
    newHoverItems.forEach(el => {
        el.addEventListener('mouseenter', () => {
            cursor.classList.add('hover');
            follower.classList.add('hover');
        }, { passive: true });
        el.addEventListener('mouseleave', () => {
            cursor.classList.remove('hover');
            follower.classList.remove('hover');
        }, { passive: true });
    });
}

// Priority Preload for Work 01 (Blender) & Work 02 (After Effects) + Smart Lazy Load for Cards 09-23
(function initPriorityMediaLoading() {
    // 1. Immediately start pre-fetching the 3 videos of Work 02 sequentially (Apple -> Coca cola -> Композиция)
    const aeWorks = [
        { src: 'Apple.mp4', fallbacks: ['Apple .mp4', 'Копия Apple .mp4', 'after_effects/Apple.mp4'] },
        { src: 'Coca cola.mp4', fallbacks: ['Coca Cola.mp4', 'after_effects/Coca_cola.mp4'] },
        { src: 'Композиция.mp4', fallbacks: ['Logo_Motion.mp4', 'after_effects/Logo_Motion.mp4'] }
    ];
    prefetchVideoToBlob(aeWorks[0])
        .then(() => prefetchVideoToBlob(aeWorks[1]))
        .then(() => prefetchVideoToBlob(aeWorks[2]));

    // 2. Lazy-load Cards 09-23 only when scrolled near viewport AND when modal is not open
    const lazyImgs = document.querySelectorAll('img[data-src]');
    const loadLazyImg = (img) => {
        const rawSrc = img.getAttribute('data-src');
        if (!rawSrc) return;
        img.removeAttribute('data-src');
        if (modal && modal.classList.contains('active')) {
            img.dataset.pausedSrc = encodeURI(rawSrc);
            pausedBgImages.push(img);
        } else {
            img.src = encodeURI(rawSrc);
        }
    };

    if ('IntersectionObserver' in window) {
        const io = new IntersectionObserver((entries, observer) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    observer.unobserve(entry.target);
                    loadLazyImg(entry.target);
                }
            });
        }, { rootMargin: '140px 0px' });
        lazyImgs.forEach(img => io.observe(img));
    } else {
        lazyImgs.forEach(loadLazyImg);
    }

    // 3. Auto-retry portfolio images if network drops
    document.querySelectorAll('.item-image img').forEach(img => {
        img.addEventListener('error', function onImgError() {
            const rawAttr = img.getAttribute('data-src') || img.dataset.pausedSrc || img.getAttribute('src');
            if (!rawAttr || rawAttr.startsWith('data:')) return;
            const retryCount = parseInt(img.dataset.retry || '0', 10);
            if (retryCount < 3) {
                img.dataset.retry = String(retryCount + 1);
                setTimeout(() => {
                    const clean = rawAttr.split('?retry=')[0];
                    img.src = encodeURI(clean) + '?retry=' + (retryCount + 1);
                }, 800 * (retryCount + 1));
            }
        });
    });
})();



